/* Global Styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
}

header {
  background-color: #0078d7;
  color: #ffffff;
  padding: 1em;
  text-align: center;
}

nav {
  background-color: #ffffff;
  padding: 1em;
  text-align: center;
}

nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

nav li {
  display: inline-block;
  margin-right: 20px;
}

nav a {
  color: #0078d7;
  text-decoration: none;
}

main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2em;
}

footer {
  background-color: #0078d7;
  color: #ffffff;
  padding: 1em;
  text-align: center;
  clear: both;
}

/* Responsive Design */
@media only screen and (max-width: 375px) {
  main {
    padding: 1em;
  }
}
